import{_ as t,c as p,o as a,ag as o}from"./chunks/framework.Sr95JMjc.js";const r="/images/posts/kepco-apply-peak-power/01.png",m=JSON.parse('{"title":"최대수요전력과 요금적용전력","description":"","frontmatter":{"title":"최대수요전력과 요금적용전력","date":"2025-08-18T14:00:00.000Z","tags":["전기요금","최대수요전력","요금적용전력"]},"headers":[],"relativePath":"posts/kepco-apply-peak-power.md","filePath":"posts/kepco-apply-peak-power.md","lastUpdated":1777690183000}'),s={name:"posts/kepco-apply-peak-power.md"};function n(c,e,l,_,i,k){return a(),p("div",null,[...e[0]||(e[0]=[o('<p><img src="'+r+'" alt=""></p><h4 id="제-68-조-요금적용전력의-결정" tabindex="-1">제 68 조 요금적용전력의 결정 <a class="header-anchor" href="#제-68-조-요금적용전력의-결정" aria-label="Permalink to &quot;제 68 조 요금적용전력의 결정&quot;">​</a></h4><blockquote><p>최대수요전력을 계량할 수 있는 전력량계를 설치한 고객은 검침 당월을 포함한 직전 12개월 중 동계(12월, 1월, 2월)와 하계(7월, 8월, 9월) 그리고 검침 당월분의 최대수요전력 중 가장 큰 최대수요전력을 요금적용전력으로 한다. 단, 최대수요전력이 계약전력의 30% 미만인 경우 계약전력의 30%를 요금적용전력으로 한다.</p></blockquote><p>일반용 또는 산업용 전기 사용에 대한 기본 요금은 위 조건에 따라 계약전력이 아닌 <strong>최대수요전력을 요금적용전력으로 하여 기본 요금을 산정</strong>한다. 일반적으로 최대수요전력은 계절별 경부하 시간대를 제외한 15분 전기 사용량의 4배한 값을 수요 전력으로 하여 가장 높은값이라고 이야기 한다. 하지만, 위 화면에서 볼 수 있듯이 <a href="https://pp.kepco.co.kr/" target="_blank" rel="noreferrer">한전 파워플래너</a>에서 확인할 수 있는 최대수요전력과 청구 요금 계산 시 적용되는 요금적용전력이 다르다는 것을 알 수 있다. 그러므로, <strong>최대수요전력량계로 검침되는 값은 15분 간 전력 사용량으로 환산한 최대수요전력과는 상이하다</strong>는 것을 의미한다.</p><p>과연 어떤 비밀이 숨어있는 것일까?</p>',5)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
